void print_usage(const char* program_name)
{
    printf("Usage: %s [-t input_file output_file] [-r iterations output_file] [-h]\n", program_name);
    printf("This program validate the signature content of <input_file>(KAT file) using dilithium algo and write result to output file <output_file>\n");
    printf("\npositional arguments:\n");
    printf("\t-t input_file output_file         Validate the given KAT file and result will be in output_file\n");
    printf("\t\tOptional arg - output_file\n");
    printf("\t-r iterations output_file         Execute random test vector (i.e with known pub key but random message hash and signature)\n");
    printf("\t\tOptional arg - output_file\n");
    printf("\t\tMax iterations accepted: 4,29,49,67,295\n");
    printf("\nOptional Arguments:\n");
    printf("-h                                  Print this help message.\n");
    printf("\nExample:\n");
    printf("  %s -t input.txt output.txt\n", program_name);
    printf("  %s -r 1000 random_output.txt\n", program_name);
}


int findMarker(FILE* infile, const char* marker)
{
    char    line[MAX_MARKER_LEN];
    int     i, len;
    int curr_line;

    len = (int)strlen(marker);

    if ( len > MAX_MARKER_LEN - 1 )
    {
        len = MAX_MARKER_LEN - 1;
    }

    for ( i = 0; i < len; i++ )
    {
        curr_line = fgetc(infile);
        line[i] = curr_line;

        if (curr_line == EOF )
        {
            return 0;
        }
    }

    line[len] = '\0';

    while ( 1 )
    {
        if ( !strncmp(line, marker, len) )
        {
            return 1;
        }

        for ( i = 0; i < len - 1; i++ )
        {
            line[i] = line[i + 1];
        }

        curr_line = fgetc(infile);
        line[len - 1] = curr_line;

        if (curr_line == EOF )
        {
            return 0;
        }

        line[len] = '\0';
    }

    // shouldn't get here
    return 0;
}

//
// ALLOW TO READ HEXADECIMAL ENTRY (KEYS, DATA, TEXT, etc.)
//
int readHex(FILE* infile, unsigned char* A, int Length, char* str)
{
    int         i, ch, started;
    unsigned char   ich;

    if ( Length == 0 )
    {
        A[0] = 0x00;
        return 1;
    }

    memset(A, 0x00, Length);
    started = 0;

    if ( findMarker(infile, str) )
        while ( (ch = fgetc(infile)) != EOF )
        {
            if ( !isxdigit(ch) )
            {
                if ( !started )
                {
                    if ( ch == '\n' )
                    {
                        break;
                    }
                    else
                    {
                        continue;
                    }
                }
                else
                {
                    break;
                }
            }

            started = 1;

            if ( (ch >= '0') && (ch <= '9') )
            {
                ich = ch - '0';
            }
            else if ( (ch >= 'A') && (ch <= 'F') )
            {
                ich = ch - 'A' + 10;
            }
            else if ( (ch >= 'a') && (ch <= 'f') )
            {
                ich = ch - 'a' + 10;
            }
            else // shouldn't ever get here
            {
                ich = 0;
            }

            for ( i = 0; i < Length - 1; i++ )
            {
                A[i] = (A[i] << 4) | (A[i + 1] >> 4);
            }

            A[Length - 1] = (A[Length - 1] << 4) | ich;
        }
    else
    {
        return 0;
    }

    return 1;
}

void writeVerifyParamToOutputFile (FILE* i_file, uint32_t i_count, uint8_t* i_msg, uint32_t i_msgLen, uint8_t* i_pk,
                                   uint8_t* i_sign, int i_result)
{
    fprintf (i_file, "--------------------------------- count: %02d ----------------------------------\n", i_count);
    fprintf (i_file, "msglen = %d\n", i_msgLen);
    fprintf (i_file, "msg    = ");

    for (int i = 0; i < i_msgLen; i++)
    {
        fprintf (i_file, "%02X", i_msg[i]);
    }

    fprintf (i_file, "\n");

    if (i_pk)
    {
        fprintf (i_file, "pk     = ");

        for (int i = 0; i < DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE; i++)
        {
            fprintf (i_file, "%02X", i_pk[i]);
        }

        fprintf (i_file, "\n");
    }

    if (i_sign)
    {
        fprintf (i_file, "sm     = ");

        for (int i = 0; i < DILITHIUM_R2_5_CRYPTO_SIG_SIZE; i++)
        {
            fprintf (i_file, "%02X", i_sign[i]);
        }

        fprintf (i_file, "\n");
    }

    fprintf (i_file, "Result  = %s\n", (i_result <= 0) ? "FAIL" : "SUCCESS");
    fprintf (i_file, "\n\n");
}


int validateKatFile(char* i_inputfile, char* i_outputfile)
{
    int                 errorCount = 0;
    int                 error_code = 0;
    int                 done = 0;
    int                 idx = 0;
    int                 count = 0;
    int                 ret_val;

    unsigned char       msg[3300];

    size_t              mlen, smlen, mlen1;

    unsigned char*       m, *sm, *m1, *m_rsp;
    unsigned char*       pk;

    printf ("Verifying KAT vectors.");

    pk = (unsigned char*) calloc(DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE, sizeof(unsigned char));

    FILE* katFile = fopen(i_inputfile, "r");

    if (katFile == NULL)
    {
        perror("Error opening input file\n");
        return 1; // Exit with error code
    }

    FILE* outputFile = fopen(i_outputfile, "w");

    if (outputFile == NULL)
    {
        perror("Error opening output file\n");
        fclose(katFile);
        return 1; // Exit with error code
    }

    do
    {
        // get the cout value from FILE
        if ( findMarker(katFile, "count = ") )
        {
            if (fscanf(katFile, "%d", &count) != 1)
            {
                printf ("can't find count value in %d\n", __LINE__);
                done = 1;
                break;
            }
        }
        else
        {
            printf ("Read full file\n");
            done = 1;
            break;
        }

        // get the message length value from FILE
        if ( findMarker(katFile, "mlen = ") )
        {
            fscanf(katFile, "%zd", &mlen);
        }
        else
        {
            printf("ERROR: unable to read 'mlen' from <%s>\n", katFile);
            return -2;
        }

        // Calucalate the max signature len
        size_t maxSignLen = mlen + DILITHIUM_R2_5_CRYPTO_SIG_SIZE;

        // Allocate space for message data
        m  = (unsigned char*)calloc(mlen, sizeof(unsigned char));
        m1 = (unsigned char*)calloc(mlen, sizeof(unsigned char));
        // Allocate space for signature data
        sm = (unsigned char*)calloc(maxSignLen, sizeof(unsigned char));

        // Read message from file and convert it to hex
        if ( !readHex(katFile, m, (int)mlen, (char*)"msg = ") )
        {
            printf("ERROR: unable to read 'msg' from <%s>\n", katFile);
            return -3;
        }

        // Read public key from KAT file and convert it to hex
        if ( !readHex(katFile, pk, DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE, (char*)"pk = ") )
        {
            printf("ERROR: unable to read 'pk' from <%s>\n", katFile);
            return -4;
        }

        if ( !readHex(katFile, sm, maxSignLen, (char*)"sm = ") )
        {
            printf("ERROR: unable to read 'sm' from <%s>\n", katFile);
            return -5;
        }

        ret_val = 0;

        if ( (ret_val = r2_verify (sm, DILITHIUM_R2_5_CRYPTO_SIG_SIZE, m, mlen, pk,
                                   DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE)) <= 0)
        {
            printf("signature verification failed, returned <%d>, count: %d\n", ret_val, count);
            errorCount++;
        }

#if 0
        printf ("\n\n\n--------------------------------- count: %02d ----------------------------------\n", count);
        printf ("index  = %02d\n", idx);
        printf ("mlen: %d\n", mlen);
        printf ("msg: ");

        for (int i = 0; i < mlen; i++)
        {
            printf ("%02X", m[i]);
        }

        printf("\r\n");

        printf ("pk: ");

        for (int i = 0; i < DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE; i++)
        {
            printf ("%02X", pk[i]);
        }

        printf("\r\n");

        printf ("sm: ");

        for (int i = 0; i < DILITHIUM_R2_5_CRYPTO_SIG_SIZE; i++)
        {
            printf ("%02X", sm[i]);
        }

        printf("\r\n");

        printf ("r2_verify ret val: %d\n", ret_val);
#endif

        // Writing result to out file
        writeVerifyParamToOutputFile(outputFile, count, m, mlen, pk, sm, ret_val);

        idx++;
    }
    while(!done);

    printf ("\nStatus : %d error\n\n", errorCount);
    fprintf (outputFile, "\n\nStatus : %d error\n\n", errorCount);

    // Close both the input and output files
    fclose(katFile);
    fclose(outputFile);

    return errorCount;
}


