void generateMsg(uint8_t* msg, uint32_t* msgLen)
{
    static uint32_t l_msgLen = 33; // default msg len

    l_msgLen += 33;

    if ( 3300 > l_msgLen)
    {
        l_msgLen = 33;
    }

    for (int i = 0; i < l_msgLen; i++)
    {
        msg[i] = rand() % 0xFF; // generate random number between 0 to 255
    }

    *msgLen = l_msgLen;
}

void generateSignature(uint8_t* signature)
{
    for (int i = 0; i < DILITHIUM_R2_5_CRYPTO_SIG_SIZE; i++)
    {
        signature[i] = rand() % 0xFF; // generate random number between 0 to 255
    }
}

int randomVectorValidate (uint32_t i_iteration, char* i_outputFile)
{
    int ret_val = 0;
    uint32_t errorCount = 0;
    uint32_t msgLen = 0;
    uint8_t msg[4000] = {0};
    uint8_t signature[DILITHIUM_R2_5_CRYPTO_SIG_SIZE] = {0};

    FILE* outputFile = fopen(i_outputFile, "w");

    if (outputFile == NULL)
    {
        perror("Error opening output file\n");
        return 1; // Exit with error code
    }

    srand(time(NULL)); //use current time as seed for random generator

    printf ("\nVerifying one KAT vector before Random vector test\n");
    fprintf (outputFile, "\nVerifying one KAT vector before Random vector test\n");

    ret_val = r2_verify ( fixed_dil_sign, DILITHIUM_R2_5_CRYPTO_SIG_SIZE,
                          fixed_sample_msg, sizeof(fixed_sample_msg),
                          fixed_public_key, DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE);
    printf ("Result of KAT: %s\n", ret_val ? "Pass" : "Fail");

    writeVerifyParamToOutputFile(outputFile, 0, fixed_sample_msg, sizeof(fixed_sample_msg), fixed_public_key,
                                 fixed_dil_sign, ret_val);

    printf ("\n\nStarted generating RANDOM message and signature...\n");
    fprintf (outputFile, "\n\nStarted generating RANDOM message and signature...\n");

    for (int i = 0 ; i < i_iteration; i++)
    {
        generateMsg(msg, &msgLen);
        generateSignature(signature);

        if ( (ret_val = r2_verify ( signature, DILITHIUM_R2_5_CRYPTO_SIG_SIZE,
                                    msg, msgLen,
                                    fixed_public_key, DILITHIUM_R2_5_CRYPTO_PUBLICKEY_SIZE)) <= 0)
        {
            errorCount++;
        }

        writeVerifyParamToOutputFile(outputFile, i, msg, msgLen, fixed_public_key, signature, ret_val);
    }

    printf ("\n\nNumber fo iteration: %d, Number of Error : %d error\n\n", i_iteration, errorCount);
    fprintf (outputFile, "\n\nNumber fo iteration: %d, Number of Error : %d error\n\n", i_iteration, errorCount);

    // Close both the input and output files
    fclose(outputFile);


    if (i_iteration != errorCount)
    {
        return errorCount;
    }

    return 0;
}


/**
 * @brief Main function of the program.
 *
 * @param argc The number of command-line arguments.
 * @param argv The array of command-line arguments.
 * @return int Returns 0 on success, non-zero on failure.
 */
int main(int argc, char* argv[])
{
    int ret_val = -1;

    printf("\n--- Program started ---\n");

    // Check if the help option is provided
    if (argc == 2 && (strcmp(argv[1], "-h") == 0))
    {
        print_usage(argv[0]);
        ret_val = 0;
    }

    // Random vector test
    else if (strcmp(argv[1], "-r") == 0)
    {
        uint64_t iterations = 1000; //default value

        if (argc >= 3)
        {
            iterations = atoi(argv[2]);
        }

        char* outputFilename = (char*)"./output.txt";

        if (argc >= 4)
        {
            outputFilename = argv[3];
        }

        printf ("\nValidation of KAT vector start...\n");
        printf ("iterations : %d\n", iterations);
        printf ("Output file: %s\n", outputFilename);

        ret_val = randomVectorValidate (iterations, outputFilename);
        printf ("randomVectorValidate return value: %d\n", ret_val);
    }

    // Testing KAT using input.txt and write result to output.txt
    else if  (strcmp(argv[1], "-t") == 0)
    {
        char* inputFilename  = argv[2];
        char* outputFilename = (char*)"./output.txt";

        if (argc >= 4)
        {
            outputFilename = argv[3];
        }

        printf ("\nValidation of KAT vector start...\n");
        printf ("Input file : %s\n", inputFilename);
        printf ("Output file: %s\n", outputFilename);

        ret_val = validateKatFile(inputFilename, outputFilename);
        printf ("validateKatFile return value: %d\n", ret_val);
    }

    else
    {
        printf ("Error: Invalid arg passed\n\n");
        print_usage(argv[0]);
    }

    // Print success message to stdout
    printf("--- Program ended ---\n");

    return ret_val; // Exit with success code
}